do $$ begin
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon; end if;
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if;
end $$;

create schema auth;
create function auth.uid() returns uuid language sql stable
as $$ select nullif(current_setting('app.test_user_id', true), '')::uuid $$;
create table auth.users (id uuid primary key);
create table public.worth_it_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  worth_it_id bigint not null unique,
  username text,
  display_name text,
  avatar_url text,
  last_seen_at timestamptz
);
create table public.worth_it_user_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  show_online_status boolean not null default true
);
create table public.worth_it_chat_conversations (
  id uuid primary key,
  conversation_type text not null check (conversation_type in ('global','direct','group')),
  title text,
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now(),
  invite_token text
);
create table public.worth_it_chat_members (
  conversation_id uuid not null references public.worth_it_chat_conversations(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  last_read_at timestamptz,
  primary key (conversation_id,user_id)
);
create table public.worth_it_chat_messages (
  id bigint generated by default as identity primary key,
  conversation_id uuid not null references public.worth_it_chat_conversations(id) on delete cascade,
  sender_user_id uuid not null references auth.users(id) on delete cascade,
  body text not null default '',
  media_url text,
  media_type text,
  filtered_reason text,
  created_at timestamptz not null default now()
);

